# Get the auto-registered DemoAgent instance from the registry
def _get_demo_instance() -> DemoAgent:
    BrainAgent._register_all()
    agent = BrainAgent._registry.get("start_demo")
    assert isinstance(agent, DemoAgent)
    return agent


